/** Child-process `UnitRunner`: spawn, messaging, exit tracking. */
import { fork } from 'node:child_process';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { WARNED_TSCONFIGS_ENV, warnedTsconfigs } from '../../config/tsconfig.js';
import { InfrastructureError } from '../../internal/errors.js';
/**
 * Resolves the worker entry for both src (vitest, .ts) and dist (.js)
 * layouts. From source, e2e's own loader is registered before the entry
 * loads (`config/register.ts`): Node.js strips types but does not compile
 * the rest of TypeScript.
 */
function resolveEntry() {
    const js = fileURLToPath(new URL('./entry.js', import.meta.url));
    if (existsSync(js))
        return { path: js, execArgv: [] };
    const ts = fileURLToPath(new URL('./entry.ts', import.meta.url));
    if (existsSync(ts)) {
        return { path: ts, execArgv: ['--import', new URL('../../config/register.ts', import.meta.url).href] };
    }
    throw new InfrastructureError('WORKER_ENTRY_MISSING', 'e2e worker entry module not found');
}
/** Creates the spawn factory the scheduler uses for child-process execution. */
export function childProcessSpawner(options) {
    const { envFor, ...bootstrap } = options;
    return (targetName, workerSlot, events) => new ChildProcessRunner({ ...bootstrap, targetName, workerSlot }, { projectRoot: bootstrap.projectRoot, env: envFor(targetName) }, events);
}
/** One live worker process bound to a single target. */
class ChildProcessRunner {
    exit;
    child;
    exited = false;
    constructor(bootstrap, spawn, events) {
        const entry = resolveEntry();
        this.child = fork(entry.path, [], {
            cwd: spawn.projectRoot,
            execArgv: entry.execArgv,
            stdio: ['ignore', 'inherit', 'inherit', 'ipc'],
            // Collecting read the project's tsconfig.json files first; the worker warns only about ones it reaches on its own.
            env: { ...spawn.env, [WARNED_TSCONFIGS_ENV]: warnedTsconfigs() },
        });
        this.child.on('message', (message) => events.onMessage(message));
        this.exit = new Promise((resolve) => {
            // 'close', not 'exit': it fires once the IPC channel has drained, so
            // every message the worker sent (its shutdown-done included) has been
            // delivered before the scheduler treats the worker as gone.
            this.child.once('close', (code, signal) => {
                this.exited = true;
                events.onExit(`code ${String(code)}, signal ${String(signal)}`, signal);
                resolve();
            });
        });
        // Spawn failures surface through the close event. A send the channel
        // could not take reports here too, on the next tick and once per send.
        this.child.on('error', () => undefined);
        this.post({ type: 'bootstrap', bootstrap });
    }
    get alive() {
        return !this.exited;
    }
    send(message) {
        this.post(message);
    }
    post(message) {
        // The channel closes ahead of the process: a send after `disconnect`
        // would not arrive, and would raise an error event instead.
        if (this.exited || !this.child.connected)
            return;
        try {
            this.child.send(message);
        }
        catch {
            // channel already closed; the exit event handles cleanup
        }
    }
    kill() {
        if (!this.exited)
            this.child.kill('SIGKILL');
    }
}
